SELECT a.CSNAME AS `股票名称`, a.COMB_SYMBOL AS `股票代码`, b.TRADE_DATE AS `交易日期`, ROUND(b.OPEN_PRICE, 2) AS `开盘价（美元）`, ROUND(b.HIGH_PRICE, 2) AS `最高价（美元）`, ROUND(b.LOW_PRICE, 2) AS `最低价（美元）`, ROUND(b.CLOSE_PRICE, 2) AS `收盘价（美元）`, ROUND(b.PRE_CLOSE, 2) AS `昨收价（美元）`, ROUND(b.CHG, 2) AS `涨跌额（美元）`, ROUND(b.CHG_PCT_DAY, 2) AS `涨跌幅（%）`, ROUND(b.TRADE_AMOUNT/100000000, 2) AS `成交额（亿美元）`, ROUND(b.TRADE_VOLUME/100000000, 2) AS `成交量（亿股）`, ROUND(b.TOTAL_SHARES/100000000, 2) AS `总股本（亿股）` FROM AMERICAN_STOCK_MAIN a JOIN VIEW_US_EOD_EXPR b ON a.FIU_ID = b.FIU_ID WHERE a.CSNAME LIKE '%阿里巴巴%' AND b.TRADE_DATE = (SELECT MAX(TRADE_DATE) FROM VIEW_US_EOD_EXPR WHERE FIU_ID = a.FIU_ID AND CLOSE_PRICE IS NOT NULL) AND b.CLOSE_PRICE IS NOT NULL;
